INSERT INTO `contract` VALUES (1,'VulnBank','// SPDX-License-Identifier: MIT\n// 漏洞样本：权限越权 + selfdestruct 后门 + 硬编码 owner\n// 用于测试 privilege_check 与 dynamic_penetrate 模块\npragma solidity ^0.8.0;\n\ncontract VulnBank {\n    // 硬编码管理员地址（规则 4：硬编码管理员）\n    address public owner = 0xAb8483F64d9C6d1EcF9b849Ae677dD3315835cb2;\n\n    mapping(address => uint256) public balances;\n\n    // 规则 2：setOwner 无权限保护 -> 任意地址可接管\n    function setOwner(address _newOwner) public {\n        owner = _newOwner;\n    }\n\n    // 规则 3：selfdestruct 后门\n    function kill() public {\n        selfdestruct(payable(msg.sender));\n    }\n\n    // 规则 1：状态变更函数缺少权限控制\n    function withdraw(uint256 amount) public {\n        balances[msg.sender] -= amount;\n        payable(msg.sender).transfer(amount);\n    }\n\n    function deposit() public payable {\n        balances[msg.sender] += msg.value;\n    }\n\n    // 规则 5：tx.origin 鉴权\n    function transferOwner(address _to) public {\n        require(tx.origin == owner, \"not owner\");\n        owner = _to;\n    }\n}\n',1,'2026-09-12 14:49:00',0),(2,'OverflowToken','// SPDX-License-Identifier: MIT\n// 漏洞样本：整数溢出（Solidity 0.7 无溢出检查）+ 重入风险\n// 用于测试 slither 静态分析\npragma solidity ^0.7.6;\n\ncontract OverflowToken {\n    mapping(address => uint256) public balances;\n    uint256 public totalSupply;\n\n    function transfer(address to, uint256 amount) public returns (bool) {\n        // 整数溢出：balances[to] + amount 可能溢出\n        balances[msg.sender] -= amount;\n        balances[to] += amount;\n        return true;\n    }\n\n    function mint(uint256 amount) public {\n        // 缺少权限控制 + 溢出\n        balances[msg.sender] += amount;\n        totalSupply += amount;\n    }\n\n    // 重入漏洞：先转账后更新余额\n    function withdraw(uint256 amount) public {\n        require(balances[msg.sender] >= amount);\n        (bool ok, ) = msg.sender.call{value: amount}(\"\");\n        require(ok);\n        balances[msg.sender] -= amount;\n    }\n}\n',1,'2026-09-12 14:49:00',0),(3,'VulnBank','// SPDX