DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '账号',
  `password_md5` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'MD5加密密码',
  `role` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '角色：admin/user',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active' COMMENT '账号状态：active/disabled',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
