DROP TABLE IF EXISTS `vulnerability`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vulnerability` (
  `id` int NOT NULL AUTO_INCREMENT,
  `audit_id` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联审计ID',
  `vul_type` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '漏洞类型',
  `risk_level` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '风险等级：高危/中危/低危',
  `location` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT '漏洞位置（行号/函数名）',
  `description` text COLLATE utf8mb4_general_ci COMMENT '漏洞描述',
  `suggestion` text COLLATE utf8mb4_general_ci COMMENT '修复建议',
  PRIMARY KEY (`id`),
  KEY `ix_vul_audit_id` (`audit_id`),
  KEY `ix_vul_risk_level` (`risk_level`)
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
