INSERT INTO `vulnerability` VALUES (1,'AUD202609121449045EC54CBF','tx.origin鉴权缺陷','高危','第24行','代码中使用 tx.origin 做身份校验，存在钓鱼合约中间人攻击风险：受害者在钓鱼合约触发本合约代码时，tx.origin 仍是受害者地址，导致鉴权被绕过。','使用 msg.sender 替代 tx.origin 进行权限校验。'),(2,'AUD202609121449045EC54CBF','任意自毁','高危','第10行','存在 selfdestruct 调用，若自毁入口无权限控制或目标可指定，合约将被销毁且资金可被强制转移。','为 selfdestruct 添加 onlyOwner 等强权限校验，并审计其调用路径。'),(3,'AUD202609121449045EC54CBF','外部调用重入风险','中危','第17行','函数内存在对外部地址的以太转账/调用，若在状态更新前执行且无重入保护，攻击者可利用 fallback 重入本函数重复提取资金。','遵循 Checks-Effects-Interactions 模式，先更新状态再外部调用，并引入 ReentrancyGuard 的 nonReentrant 修饰符。'),(4,'AUD202609121449045EC54CBF','未授权访问风险','高危','第13行 setOwner(address _newOwner)','对外接口 setOwner(address _newOwner) 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(5,'AUD202609121449045EC54CBF','未授权访问风险','高危','第18行 kill()','对外接口 kill() 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(6,'AUD202609121449045EC54CBF','未授权访问风险','高危','第23行 withdraw(uint256 amount)','对外接口 withdraw(uint256 amount) 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(7,'AUD202609121449045EC54CBF','未授权访问风险','高危','第28行 deposit()','对外接口 deposit() 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。该函数可支付 ETH（payable）。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(8,'AUD202609121449045EC54CBF','未授权访问风险','高危','第33行 transferOwner(address _to)','对外接口 transferOwner(address _to) 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(9,'AUD202609121449045EC54CBF','参数边界校验缺失风险','中危','第23行 withdraw(uint256 amount) 参数 amount','对外接口 withdraw 的数值参数 amount（uint256，256位）未检测到 require/if 范围校验。渗透测试边界 Fuzz 输入 [0, 115792089237316195423570985008687907853269984665640564039457584007913129639935, 负数（uint 下溢回滚，链上视为无效输入）] 时，超范围值可直达业务逻辑，可能引发下溢/上溢、索引越界或逻辑绕过。','在函数入口对 amount 添加范围校验，如 require(amount > 0 && amount <= 合理上限)，拦截 0、类型最大值（115792089237316195423570985008687907853269984665640564039457584007913129639935）等边界输入。'),(10,'AUD20260912144904A817DAFB','外部调用重入风险','中危','第21行','函数内存在对外部地址的以太转账/调用，若在状态更新前执行且无重入保护，攻击者可利用 fallback 重入本函数重复提取资金。','遵循 Checks-Effects-Interactions 模式，先更新状态再外部调用，并引入 ReentrancyGuard 的 nonReentrant 修饰符。'),(11,'AUD20260912144904A817DAFB','未检查底层调用返回值','低危','第21行','底层 call 调用的返回值（bool）未被检查，调用失败时不会回滚，可能导致合约状态与资金流不一致。','对 call 返回值使用 require 判断，或改用带返回值检查的封装。'),(12,'AUD20260912144904A817DAFB','整数溢出风险','中危','全局','编译版本低于 0.8.0 且未引入 SafeMath，加减乘运算可能发生整数上溢/下溢。','升级编译器至 ^0.8.0，或全部算术运算改用 SafeMath 库。'),(13,'AUD20260912144904A817DAFB','未授权访问风险','高危','第10行 transfer(address to, uint256 amount)','对外接口 transfer(address to, uint256 amount) 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(14,'AUD20260912144904A817DAFB','未授权访问风险','高危','第17行 mint(uint256 amount)','对外接口 mint(uint256 amount) 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(15,'AUD20260912144904A817DAFB','未授权访问风险','高危','第24行 withdraw(uint256 amount)','对外接口 withdraw(uint256 amount) 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(16,'AUD20260912144904A817DAFB','参数边界校验缺失风险','中危','第10行 transfer(address to, uint256 amount) 参数 amount','对外接口 transfer 的数值参数 amount（uint256，256位）未检测到 require/if 范围校验。渗透测试边界 Fuzz 输入 [0, 115792089237316195423570985008687907853269984665640564039457584007913129639935, 负数（uint 下溢回滚，链上视为无效输入）] 时，超范围值可直达业务逻辑，可能引发下溢/上溢、索引越界或逻辑绕过。','在函数入口对 amount 添加范围校验，如 require(amount > 0 && amount <= 合理上限)，拦截 0、类型最大值（115792089237316195423570985008687907853269984665640564039457584007913129639935）等边界输入。'),(17,'AUD20260912144904A817DAFB','参数边界校验缺失风险','中危','第17行 mint(uint256 amount) 参数 amount','对外接口 mint 的数值参数 amount（uint256，256位）未检测到 require/if 范围校验。渗透测试边界 Fuzz 输入 [0, 115792089237316195423570985008687907853269984665640564039457584007913129639935, 负数（uint 下溢回滚，链上视为无效输入）] 时，超范围值可直达业务逻辑，可能引发下溢/上溢、索引越界或逻辑绕过。','在函数入口对 amount 添加范围校验，如 require(amount > 0 && amount <= 合理上限)，拦截 0、类型最大值（115792089237316195423570985008687907853269984665640564039457584007913129639935）等边界输入。'),(18,'AUD202609171000416EFFEB92','tx.origin鉴权缺陷','高危','第24行','代码中使用 tx.origin 做身份校验，存在钓鱼合约中间人攻击风险：受害者在钓鱼合约触发本合约代码时，tx.origin 仍是受害者地址，导致鉴权被绕过。','使用 msg.sender 替代 tx.origin 进行权限校验。'),(19,'AUD202609171000416EFFEB92','任意自毁','高危','第10行','存在 selfdestruct 调用，若自毁入口无权限控制或目标可指定，合约将被销毁且资金可被强制转移。','为 selfdestruct 添加 onlyOwner 等强权限校验，并审计其调用路径。'),(20,'AUD202609171000416EFFEB92','外部调用重入风险','中危','第17行','函数内存在对外部地址的以太转账/调用，若在状态更新前执行且无重入保护，攻击者可利用 fallback 重入本函数重复提取资金。','遵循 Checks-Effects-Interactions 模式，先更新状态再外部调用，并引入 ReentrancyGuard 的 nonReentrant 修饰符。'),(21,'AUD202609171000416EFFEB92','未授权访问风险','高危','第13行 setOwner(address _newOwner)','对外接口 setOwner(address _newOwner) 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(22,'AUD202609171000416EFFEB92','未授权访问风险','高危','第18行 kill()','对外接口 kill() 为 public 函数，可被任意地址直接调用修改合约状态，未检测到访问控制修饰符或 msg.sender 权限校验，属于渗透测试中的\'未授权访问\'风险点。','为该函数添加访问控制：引入 onlyOwner/onlyAdmin 等修饰符，或在函数体内校验 msg.sender 权限；若设计上确需公开调用，请确认其对状态与资金的影响并做输入校验。'),(23,'AUD202609171000416EFFEB92','未授权访问风险','高危','第23行 withdraw(uint256 amount)','对外接口 withdraw(uint256 amount) 为 public 函数，可被任意地址直接调用修改